<?php require_admin();$orders=q('SELECT c.*,u.nombre usuario,u.correo FROM compras c JOIN usuarios u ON u.id=c.usuario_id ORDER BY c.id DESC')->fetchAll();?><div class="container py-5"><a href="index.php?page=admin">← Volver a administración</a><h1 class="my-4" style="font-size:3rem">Historial de compras</h1><div class="surface p-4"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Compra</th><th>Usuario</th><th>Productos</th><th>Total</th><th>Fecha</th><th>Estado</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td>#<?=(int)$o['id']?></td><td><?=h($o['usuario'])?><br><small class="small-muted"><?=h($o['correo'])?></small></td><td><?php foreach(q('SELECT nombre_snapshot,cantidad FROM detalle_compra WHERE compra_id=?',[$o['id']])->fetchAll() as $line): ?><div class="small"><?=h($line['nombre_snapshot'])?> × <?=(int)$line['cantidad']?></div><?php endforeach ?></td><td><?=money($o['total'])?></td><td><?=h($o['creado_en'])?></td><td><?=h($o['estado'])?></td></tr><?php endforeach ?></tbody></table></div><?php if(!$orders): ?><p class="text-muted">No se han registrado compras.</p><?php endif ?></div></div>
